"""Change the values of #defines and enum constants in a header generated by zcbor.

Only the given values are replaced, the rest of the file is left untouched.
Each name must be present exactly once, and each new value must differ from the old one."""

from argparse import ArgumentParser, ArgumentTypeError
from pathlib import Path
from re import compile, escape, MULTILINE


def name_and_value(arg):
    name, _, value = arg.partition("=")
    if not compile(r"[A-Za-z_]\w*").fullmatch(name) or not value:
        raise ArgumentTypeError(f"Expected NAME=VALUE, got '{arg}'.")
    return name, value


def modify_defines(contents, new_values):
    names = [name for name, _ in new_values]
    duplicates = {name for name in names if names.count(name) > 1}
    if duplicates:
        raise ValueError(f"Names given more than once: {', '.join(sorted(duplicates))}")

    for name, new_value in new_values:
        define_re = compile(rf"^#define {escape(name)} (?P<value>[^\r\n]+)", MULTILINE)
        enum_re = compile(rf"^[ \t]+{escape(name)} = (?P<value>[^,\r\n]+),", MULTILINE)
        matches = list(define_re.finditer(contents)) + list(enum_re.finditer(contents))
        if len(matches) != 1:
            raise ValueError(
                f"Expected exactly one '#define {name}' or enum constant '{name}', found {len(matches)}."
            )
        old_value = matches[0]["value"]
        if old_value.startswith("(") and old_value.endswith(")"):
            new_value = f"({new_value})"
        if new_value == old_value:
            raise ValueError(f"New value for {name} is the same as the old: {old_value}")
        start, end = matches[0].span("value")
        contents = contents[:start] + new_value + contents[end:]
        print(f"{name}: {old_value} -> {new_value}")
    return contents


if __name__ == "__main__":
    parser = ArgumentParser(description=__doc__)
    parser.add_argument("header", type=Path, help="The header file to modify.")
    parser.add_argument(
        "new_values", nargs="+", type=name_and_value, metavar="NAME=VALUE", help="The new values."
    )
    args = parser.parse_args()

    # Use bytes to avoid any newline conversion.
    contents = args.header.read_bytes().decode("utf-8")
    args.header.write_bytes(modify_defines(contents, args.new_values).encode("utf-8"))
